SNIPPET.JAVASCRIPT:
function member(item, x) {
    return is_null(x)
           ? null
           : item === head(x)
           ? x
           : member(item, tail(x));
}

function equal(xs, ys) {
    return is_pair(xs)
           ? (is_pair(ys) &&
              equal(head(xs), head(ys)) && 
              equal(tail(xs), tail(ys)))
           : xs === ys;
}
